                        ctx.timerService().registerEventTimeTimer(ts + (sesssize * 1000L) + 1000);
                    }

                    @Override
                    public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
                        Integer maxCount = maxCountState.value();
                        if (maxCount != null) {
                            out.collect(new Tuple2<>(ctx.getCurrentKey(), maxCount));
                            maxCountState.clear();
                            jobFinishedState.clear();
                            finishTimestampState.clear();
                        }
                    }
