package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.SerializableTimestampAssigner;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.streaming.api.functions.windowing.WindowFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        DataStream<TaskEvent> tasks = env.addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .filter(t -> t != null && t.eventType == 0)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                                .withTimestampAssigner((SerializableTimestampAssigner<TaskEvent>) (event, timestamp) -> event.timestamp / 1000)
                );

        DataStream<JobEvent> jobs = env.addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .filter(j -> j != null && j.eventType == 4)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                                .withTimestampAssigner((SerializableTimestampAssigner<JobEvent>) (event, timestamp) -> event.timestamp / 1000)
                );

        DataStream<Tuple2<Long, Integer>> sessionCounts = tasks
                .keyBy(t -> t.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .apply(new WindowFunction<TaskEvent, Tuple2<Long, Integer>, Long, TimeWindow>() {
                    @Override
                    public void apply(Long jobId, TimeWindow window, Iterable<TaskEvent> input, Collector<Tuple2<Long, Integer>> out) {
                        int count = 0;
                        for (TaskEvent ignored : input) {
                            count++;
                        }
                        out.collect(new Tuple2<>(jobId, count));
                    }
                });

        DataStream<Tuple2<Long, Integer>> result = sessionCounts
                .connect(jobs)
                .keyBy(t -> t.f0, j -> j.jobId)
                .process(new KeyedCoProcessFunction<Long, Tuple2<Long, Integer>, JobEvent, Tuple2<Long, Integer>>() {
                    private ValueState<Integer> maxCountState;
                    private ValueState<Boolean> jobFinishedState;
                    private ValueState<Long> finishTimestampState;

                    @Override
                    public void open(Configuration parameters) {
                        maxCountState = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Integer.class, 0));
                        jobFinishedState = getRuntimeContext().getState(new ValueStateDescriptor<>("jobFinished", Boolean.class, false));
                        finishTimestampState = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTimestamp", Long.class));
                    }

                    @Override
                    public void processElement1(Tuple2<Long, Integer> value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
                        int currentMax = maxCountState.value();
                        if (value.f1 > currentMax) {
                            maxCountState.update(value.f1);
                        }
                        if (jobFinishedState.value()) {
                            // If job already finished, we update the timer to ensure we output the latest max.
                            ctx.timerService().registerEventTimeTimer(finishTimestampState.value() + (sesssize * 1000L) + 1000);
                        }
                    }

                    @Override
                    public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
                        jobFinishedState.update(true);
                        long ts = value.timestamp / 1000;
                        finishTimestampState.update(ts);
                        ctx.timerService().registerEventTimeTimer(ts + (sesssize * 1000L) + 1000);
                    }

                    @Override
                    public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
                        out.collect(new Tuple2<>(ctx.getCurrentKey(), maxCountState.value()));
                    }
                });

        if (outputPath != null) {
            result.writeAsText(outputPath).setParallelism(1);
        } else {
            result.addSink(sinkOrTest(new org.apache.flink.streaming.api.functions.sink.SinkFunction<Tuple2<Long, Integer>>() {
                @Override
                public void invoke(Tuple2<Long, Integer> value, Context context) {
                    System.out.println(value);
                }
            }));
        }

        env.execute("LongestSessionPerJob");
    }

}
